export type ParsedRefundInstruction<
  TProgram extends string = typeof AXEL_V2_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Pays for its payment account if it does not exist. */
    owner: TAccountMetas[0];
    investor: TAccountMetas[1];
    project: TAccountMetas[2];
    position: TAccountMetas[3];
    shareMint: TAccountMetas[4];
    ownerShareAccount: TAccountMetas[5];
    paymentMint: TAccountMetas[6];
    ownerPaymentAccount: TAccountMetas[7];
    escrowVault: TAccountMetas[8];
    shareTokenProgram: TAccountMetas[9];
    paymentTokenProgram: TAccountMetas[10];
    associatedTokenProgram: TAccountMetas[11];
    systemProgram: TAccountMetas[12];
  };
  data: RefundInstructionData;
};

export function parseRefundInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRefundInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 13) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 13,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      owner: getNextAccount(),
      investor: getNextAccount(),
      project: getNextAccount(),
      position: getNextAccount(),
      shareMint: getNextAccount(),
      ownerShareAccount: getNextAccount(),
      paymentMint: getNextAccount(),
      ownerPaymentAccount: getNextAccount(),
      escrowVault: getNextAccount(),
      shareTokenProgram: getNextAccount(),
      paymentTokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getRefundInstructionDataDecoder().decode(instruction.data),
  };
}
